def parse_accounts(accounts):
    a = {}
    if isinstance(accounts, tuple):
        accounts = {account_type: starting_cash for account_type, starting_cash in accounts}
    for account_type, starting_cash in six.iteritems(accounts):
        if starting_cash is None:
            continue
        try:
            starting_cash = float(starting_cash)
        except (ValueError, TypeError):
            logger.strategy_log.warning(_('{account_type}账户初始化开始资金异常，开始资金{starting_cash}不是合法的数值，更改为100000'.format(account_type=account_type, starting_cash=starting_cash)))
            starting_cash = 100000
        account_type = account_type.upper()
        if starting_cash < 0:
            logger.strategy_log.warning(_('{account_type}账户初始化开始资金异常，开始资金{starting_cash}<0，更改为100000'.format(account_type=account_type, starting_cash=starting_cash)))
            starting_cash = 100000
        a[account_type] = starting_cash
    else:
        return a
def parse_init_positions(positions):
    """
    解析底仓
    :param positions: str/list
    :return: list(tuple(str, float))  标的 数量组成的元组列表
    """
    result = []
    if isinstance(positions, str):
        for s in positions.split(','):
            try:
                symbol, amount = s.split(':')
            except ValueError:
                raise RuntimeError(_("底仓初始化参数异常 position: {}, should be in format 'symbol:amount'").format(s))
            try:
                result.append((symbol, float(amount)))
            except ValueError:
                raise RuntimeError(_('底仓初始化参数异常 标的信息 {symbol}: {amount}').format(symbol=symbol, amount=amount))
    return result
def parse_run_type(rt_str):
    """
    解析运行类型
    :param rt_str: str "BACKTEST"/"SIMULATION"/"TRADING" 表示回测/仿真/交易
    :return: RunType
    """
    assert isinstance(rt_str, six.string_types)
    try:
        return const.RunType(rt_str)
    except ValueError:
        raise RuntimeError(_('不支持的运行类型: {}').format(rt_str))
def parse_matching_type(rt_str):
    """
    解析撮合方式
    :param rt_str: str "CLOSE"/"OPEN"/"NEXT_BAR_OPEN" 收盘价/开盘价/下一周期价格
    :return: MatchType
    """
    assert isinstance(rt_str, six.string_types)
    try:
        return const.MatcherType(rt_str)
    except ValueError:
        raise RuntimeError(_('不支持的撮合方式: {}').format(rt_str))
def parse_level_type(lt_str):
    """
    解析行情level类型
    :param lt_str: "LEVEL1"/"LEVEL2"
    :return: LevelType
    """
    assert isinstance(lt_str, six.string_types)
    try:
        return const.LevelType(lt_str)
    except ValueError:
        raise RuntimeError(_('不支持的日志等级: {}').format(lt_str))
def parse_logger_level(log_option):
    logger.user_log.set_log_level(logger.get_logger_level(log_option.user_log))
    logger.strategy_log.set_log_level(logger.get_logger_level(log_option.strategy_log))
    logger.system_log.set_log_level(logger.get_logger_level(log_option.system_log))
def parse_benchmark(benchmark):
    if benchmark is not None:
        return benchmark.replace('SS', 'XSHG').replace('SZ', 'XSHE')
    else:
        return benchmark
